class PanelFile {
public:
    void Draw(int layer);
};

class FEMenuEntry {
public:
    int entry_num;
    FEMenuEntry *next;
    FEMenuEntry *previous;
    void *menu;
    char data[0x50];
    virtual ~FEMenuEntry();
    virtual void Load();
    virtual void OnSelect();
    virtual void Highlight(bool highlighted = true, bool animate = true);
    virtual void Disable(bool disabled = true);
    virtual bool GetDisable();
    virtual void Draw();
};

class FEMenu {
public:
    char data0[0x40];
    FEMenuEntry *entries;
    char data1[0x1c];
    FEMenu *active;
    virtual ~FEMenu();
    virtual void setBack(FEMenu *, int = 1);
    virtual void setHigh(FEMenuEntry *, bool = true);
    virtual void setVis(FEMenuEntry *);
    virtual void Add(FEMenuEntry *);
    virtual void Init();
    virtual void Load(bool);
    virtual void Load();
    virtual void Draw();
};

class MultiLineString {
public:
    virtual ~MultiLineString();
    virtual void Draw();
};

class NamesMenu : public FEMenu {
public:
    void DrawHeader();
};

class PanelQuad {
public:
    void Mask(float amount);
    void Update(float time);
};

class DialogMenu : public FEMenu {
    char data[0xfc];
    PanelQuad *bar[4];

public:
    void SetProgress(float fl) { bar[0]->Mask(fl); bar[0]->Update(0); }
};

class SaveLoadFrontEnd : public FEMenu {
public:
    enum disp_states {
        DSTATE_LSD,
        DSTATE_LOAD,
        DSTATE_LOAD_PICK,
        DSTATE_LOAD_GLOBAL,
        DSTATE_LOADING_GLOBAL,
        DSTATE_LOADING,
        DSTATE_LOAD_DONE,
        DSTATE_SAVE,
        DSTATE_SAVE_GLOBAL,
        DSTATE_SAVE_NAME,
        DSTATE_SAVE_PICK,
        DSTATE_SAVING,
        DSTATE_SAVING_GLOBAL,
        DSTATE_SAVE_PHOTO,
        DSTATE_SAVING_PHOTO,
        DSTATE_SAVE_DONE,
        DSTATE_DELETE,
        DSTATE_DELETE_PICK,
        DSTATE_DELETING,
        DSTATE_DEL_DONE,
        DSTATE_FORMATTING,
        DSTATE_FORM_DONE
    };

    char data2[0x9c];
    PanelFile panel;
    char data3[0x3170];
    float progressval;
    char data4[0x10];
    bool flags;
    char data5[0xf];
    int dstate;
    char data6[0x28];
    MultiLineString *sftd;
    NamesMenu *NameMenu;
    char data7[4];
    DialogMenu *dialogMenu;

    virtual void Draw();
};

__asm__(".equ Draw__9PanelFilei, 0x001530B8");
__asm__(".equ Mask__9PanelQuadf, 0x0014EE58");
__asm__(".equ Update__9PanelQuadf, 0x0014F138");
__asm__(".equ DrawHeader__9NamesMenu, 0x0019F0B8");

void SaveLoadFrontEnd::Draw()
{
	// set progress bar
	if(dstate == DSTATE_SAVING || dstate == DSTATE_LOADING || dstate == DSTATE_SAVING_GLOBAL)
		dialogMenu->SetProgress(progressval);

	panel.Draw(0);

	if(active) active->Draw();
	if ((dstate == DSTATE_DELETE) ||
      (dstate == DSTATE_DELETE_PICK) ||
	    (dstate == DSTATE_DELETING) ||
	    (dstate == DSTATE_DEL_DONE))
	sftd->Draw();

	if(active == dialogMenu && dstate != DSTATE_LSD && dstate != DSTATE_SAVE_NAME)
		NameMenu->DrawHeader();

	// always draw this
	FEMenuEntry* tmp = entries;
	while(tmp)
	{
		tmp->Draw();
		tmp = tmp->next;
	}
}
